const fs = require('fs');

function solve() {
  const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
  let idx = 0;

  const Xi = data[idx++], Yi = data[idx++];
  const Xf = data[idx++], Yf = data[idx++];
  const N = data[idx++];

  const rects = [];
  for (let i = 0; i < N; i++) {
    const x1 = data[idx++], y1 = data[idx++];
    const x2 = data[idx++], y2 = data[idx++];
    rects.push({ x1, y1, x2, y2 });
  }

  const parent = Array(N).fill(0).map((_, i) => i);

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  function union(a, b) {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent[rb] = ra;
  }

  function overlap(a, b) {
    return a.x1 <= b.x2 && b.x1 <= a.x2 && a.y1 <= b.y2 && b.y1 <= a.y2;
  }

  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      if (overlap(rects[i], rects[j])) union(i, j);
    }
  }

  const rootToComp = new Map();
  const compIdx = new Array(N);
  let M = 0;

  for (let i = 0; i < N; i++) {
    const r = find(i);
    if (!rootToComp.has(r)) rootToComp.set(r, M++);
    compIdx[i] = rootToComp.get(r);
  }

  function inside(x, y) {
    for (let i = 0; i < N; i++) {
      const r = rects[i];
      if (x >= r.x1 && x <= r.x2 && y >= r.y1 && y <= r.y2) {
        return compIdx[i];
      }
    }
    return -1;
  }

  const compP = inside(Xi, Yi);
  const compQ = inside(Xf, Yf);

  let V = M;
  let startNode, finishNode;

  if (compP !== -1) startNode = compP;
  else startNode = V++;

  if (compQ !== -1) finishNode = compQ;
  else finishNode = V++;

  const distMat = Array.from({ length: V }, () => new Array(V).fill(Infinity));

  function rectDist(a, b) {
    const dx = Math.max(0, Math.max(a.x1, b.x1) - Math.min(a.x2, b.x2));
    const dy = Math.max(0, Math.max(a.y1, b.y1) - Math.min(a.y2, b.y2));
    return dx + dy;
  }

  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      const ci = compIdx[i];
      const cj = compIdx[j];
      if (ci === cj) continue;
      const d = rectDist(rects[i], rects[j]);
      if (d < distMat[ci][cj]) {
        distMat[ci][cj] = d;
        distMat[cj][ci] = d;
      }
    }
  }

  function pointRectDist(x, y, r) {
    const dx = x < r.x1 ? r.x1 - x : (x > r.x2 ? x - r.x2 : 0);
    const dy = y < r.y1 ? r.y1 - y : (y > r.y2 ? y - r.y2 : 0);
    return dx + dy;
  }

  const dStart = new Array(M).fill(Infinity);
  const dFinish = new Array(M).fill(Infinity);

  for (let i = 0; i < N; i++) {
    const c = compIdx[i];

    const ds = pointRectDist(Xi, Yi, rects[i]);
    if (ds < dStart[c]) dStart[c] = ds;

    const df = pointRectDist(Xf, Yf, rects[i]);
    if (df < dFinish[c]) dFinish[c] = df;
  }

  if (compP === -1) {
    for (let c = 0; c < M; c++) {
      distMat[startNode][c] = dStart[c];
      distMat[c][startNode] = dStart[c];
    }
  }

  if (compQ === -1) {
    for (let c = 0; c < M; c++) {
      distMat[finishNode][c] = dFinish[c];
      distMat[c][finishNode] = dFinish[c];
    }
  }

  if (compP === -1 && compQ === -1) {
    const direct = Math.abs(Xi - Xf) + Math.abs(Yi - Yf);
    distMat[startNode][finishNode] = direct;
    distMat[finishNode][startNode] = direct;
  }

  const dist = new Array(V).fill(Infinity);
  const visited = new Array(V).fill(false);
  dist[startNode] = 0;

  for (let iter = 0; iter < V; iter++) {
    let u = -1;
    let best = Infinity;

    for (let i = 0; i < V; i++) {
      if (!visited[i] && dist[i] < best) {
        best = dist[i];
        u = i;
      }
    }

    if (u === -1) break;
    if (u === finishNode) break;

    visited[u] = true;

    for (let v = 0; v < V; v++) {
      if (!visited[v]) {
        const w = distMat[u][v];
        if (w < Infinity) {
          const nd = dist[u] + w;
          if (nd < dist[v]) dist[v] = nd;
        }
      }
    }
  }

  console.log(dist[finishNode]);
}

solve();
